
import TradeSettingSaveForm from '@/Components/Forms/Backend/TradeSettingSaveForm';
import StatusBadge from '@/Components/UI/StatusBadge';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import {
    Settings,
    Timer,
    TrendingUp
} from 'lucide-react';
import z from 'zod';

export function useTradeSettingConfig(props: CrudPageProps): CrudConfig {
    const { t } = useTranslations();

    const modelProperty = props?.modelProperty;
    const advanceFilterOptions = props?.advanceFilterOptions || [];
    const routePrefix = modelProperty?.routePrefix;

    // crypto list passed from controller for the crypto selector
    const cryptoOptions = (props?.cryptos || []).map((c: any) => ({
        value: String(c.id),
        label: `${c.name} (${c.symbol})`,
    }));

    const baseBreadcrumbs = [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Trade Settings'), href: route(`${routePrefix}.index`) },
    ];

    return {
        formComponent: TradeSettingSaveForm,
        fetchToggle: false,

        form: {
            title: {
                create: t('Create Trade Setting'),
                edit: t('Edit Trade Setting'),
            },
            description: {
                create: t('Configure a trade duration option with win percentages and amount limits'),
                edit: t('Update trade setting configuration'),
            },
            submitButtonText: {
                create: t('Create Setting'),
                edit: t('Update Setting'),
            },

            fields: [
                // ── Crypto & Label ──────────────────────────────────────────

                {
                    name: 'label',
                    label: t('Duration Label'),
                    type: 'text',
                    placeholder: t('e.g. 30s, 1m, 3m'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('Label shown to users on the trade page'),
                },
                {
                    name: 'duration_seconds',
                    label: t('Duration (seconds)'),
                    type: 'number',
                    placeholder: t('e.g. 30'),
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    description: t('How long the trade countdown runs'),
                },
                {
                    name: 'status',
                    label: t('Status'),
                    type: 'select',
                    required: true,
                    section: 'basic',
                    gridColumn: 'span 1',
                    options: [
                        { value: 'active', label: t('Active') },
                        { value: 'inactive', label: t('Inactive') },
                    ],
                    description: t('Only active settings are shown on the trade page'),
                },

                // ── Win % options ───────────────────────────────────────────
                {
                    name: 'win_pct_option_a',
                    label: t('Win % — Option A'),
                    type: 'number',
                    placeholder: t('e.g. 85'),
                    required: true,
                    section: 'win',
                    gridColumn: 'span 1',
                    description: t('Profit percentage paid to the user on a winning trade (Option A)'),
                },
                {
                    name: 'win_pct_option_b',
                    label: t('Win % — Option B'),
                    type: 'number',
                    placeholder: t('e.g. 80'),
                    required: true,
                    section: 'win',
                    gridColumn: 'span 1',
                    description: t('Alternative win percentage (Option B)'),
                },
                {
                    name: 'win_pct_option_c',
                    label: t('Win % — Option C'),
                    type: 'number',
                    placeholder: t('e.g. 75'),
                    required: true,
                    section: 'win',
                    gridColumn: 'span 1',
                    description: t('Alternative win percentage (Option C)'),
                },
                {
                    name: 'display_yield_pct',
                    label: t('Display Yield %'),
                    type: 'number',
                    placeholder: t('e.g. 85'),
                    required: true,
                    section: 'win',
                    gridColumn: 'span 1',
                    description: t('Estimated yield shown to users on the trade UI (cosmetic only)'),
                },

                // ── Amount limits ───────────────────────────────────────────
                {
                    name: 'min_trade_amount',
                    label: t('Minimum Trade Amount'),
                    type: 'number',
                    placeholder: t('e.g. 10'),
                    required: true,
                    section: 'limits',
                    gridColumn: 'span 1',
                    description: t('Minimum USDT amount a user can trade'),
                },
                {
                    name: 'max_trade_amount',
                    label: t('Maximum Trade Amount'),
                    type: 'number',
                    placeholder: t('e.g. 100000'),
                    required: true,
                    section: 'limits',
                    gridColumn: 'span 1',
                    description: t('Maximum USDT amount per trade'),
                },
            ],
        },

        formValidationRules: {
            label: z.string().min(1, 'Label is required').max(50),
            duration_seconds: z.coerce.number().int().min(1, 'Duration must be at least 1 second'),
            status: z.string(),

            win_pct_option_a: z.coerce.number().min(0).max(100),
            win_pct_option_b: z.coerce.number().min(0).max(100),
            win_pct_option_c: z.coerce.number().min(0).max(100),
            display_yield_pct: z.coerce.number().min(0).max(100),

            min_trade_amount: z.coerce.number().min(0),
            max_trade_amount: z.coerce.number().min(0),

            // amount_presets handled separately in the form component
            amount_presets: z.array(z.coerce.number()).optional(),
        },

        resource: 'trade-setting',
        resourcePlural: 'trade-settings',
        title: t('Trade Settings'),
        description: t('Configure trade durations, win percentages, and amount limits per cryptocurrency'),

        routes: {
            index: `${routePrefix}.index`,
            create: `${routePrefix}.create`,
            edit: `${routePrefix}.edit`,
            store: `${routePrefix}.store`,
            update: `${routePrefix}.update`,
            destroy: `${routePrefix}.destroy`,
        },

        formDisplayMode: 'page',
        viewDisplayMode: 'page',
        statusType: 'binary',

        breadcrumbs: {
            index: [
                { label: t('Dashboard'), href: route('backend.dashboard') },
                { label: t('Trade Settings'), href: null, active: true },
            ],
            create: [
                ...baseBreadcrumbs,
                { label: t('Create Setting'), href: null, active: true },
            ],
            update: [
                ...baseBreadcrumbs,
                { label: t('Edit Setting'), href: null, active: true },
            ],
        },

        table: {
            selectable: false,
            searchable: true,
            serializable: true,
            searchPlaceholder: t('Search by label or crypto…'),
            sortable: true,
            defaultSort: 'duration_seconds',
            defaultSortDirection: 'asc',
            emptyMessage: t('No trade settings yet. Create one to enable trading.'),
            emptyMessageIcon: Settings,

            bulkActions: [
                { key: 'delete', permission: 'trade-setting.delete' },
                { key: 'active', permission: 'trade-setting.edit' },
                { key: 'inactive', permission: 'trade-setting.edit' },
            ],

            columns: [

                {
                    key: 'label',
                    label: t('Label / Duration'),
                    sortable: false,
                    priority: 1,
                    render: (row: any) => (
                        <div className="flex items-center gap-2">
                            <div className="flex items-center gap-1.5 px-2 py-1 bg-muted rounded  text-sm font-bold">
                                <Timer className="w-3.5 h-3.5" />
                                {row.label}
                            </div>
                            <span className="text-xs text-muted-foreground">{row.duration_seconds}s</span>
                        </div>
                    ),
                },
                {
                    key: 'win_pcts',
                    label: t('Win % (A / B / C)'),
                    sortable: false,
                    priority: 2,
                    render: (row: any) => (
                        <div className="flex items-center gap-1.5 text-sm ">
                            <span className="text-green-600 font-semibold">{Number(row.win_pct_option_a).toFixed(1)}%</span>
                            <span className="text-muted-foreground">/</span>
                            <span className="text-blue-600 font-semibold">{Number(row.win_pct_option_b).toFixed(1)}%</span>
                            <span className="text-muted-foreground">/</span>
                            <span className="text-orange-600 font-semibold">{Number(row.win_pct_option_c).toFixed(1)}%</span>
                        </div>
                    ),
                },
                {
                    key: 'display_yield_pct',
                    label: t('Display Yield'),
                    sortable: false,
                    priority: 2,
                    render: (row: any) => (
                        <div className="flex items-center gap-1 text-sm  font-semibold text-green-600">
                            <TrendingUp className="w-3.5 h-3.5" />
                            {Number(row.display_yield_pct).toFixed(0)}%
                        </div>
                    ),
                },
                {
                    key: 'amount_range',
                    label: t('Amount Range'),
                    sortable: false,
                    priority: 3,
                    render: (row: any) => (
                        <div className="text-xs text-muted-foreground  space-y-0.5">
                            <div>Min: <span className="text-foreground font-medium">{(row.formatted_min_trade_amount)}</span></div>
                            <div>Max: <span className="text-foreground font-medium">{(row.formatted_max_trade_amount)}</span></div>
                        </div>
                    ),
                },
                {
                    key: 'amount_presets',
                    label: t('Presets'),
                    sortable: false,
                    priority: 4,
                    render: (row: any) => {
                        const presets: number[] = row.amount_presets || [];
                        return (
                            <div className="flex flex-wrap gap-1">
                                {presets.slice(0, 4).map((p: number) => (
                                    <span key={p} className="px-1.5 py-0.5 bg-muted text-xs  rounded">
                                        {p >= 1000 ? `${p / 1000}K` : p}
                                    </span>
                                ))}
                                {presets.length > 4 && (
                                    <span className="text-xs text-muted-foreground">+{presets.length - 4}</span>
                                )}
                                {presets.length === 0 && <span className="text-xs text-muted-foreground">—</span>}
                            </div>
                        );
                    },
                },
                {
                    key: 'status',
                    label: t('Status'),
                    sortable: false,
                    priority: 3,
                    render: (row: any) => (
                        <div className="mt-1.5">
                            <StatusBadge status={row.status} />
                        </div>
                    ),
                },
            ],
        },

        filters: {
            searchFields: ['label'],
            filterFields: advanceFilterOptions,
        },

        permissions: {
            actions: {
                create: 'trade-setting.create',
                edit: 'trade-setting.edit',
                view: 'trade-setting.view',
                delete: 'trade-setting.delete',
            },
        },

        actionConstraints: {
            delete: [],
        },

        destroyDialogConfig: {
            title: t('Delete Trade Setting'),
            description: t('Are you sure you want to delete this trade setting? This cannot be undone.'),
            itemName: {
                label: t('Label'),
                key: 'label',
                render: (label: string) => label,
            },
            itemType: 'Trade Setting',
            warningMessage: t('Deleting this setting will remove it from the trade page immediately.'),
            showWarningAlert: true,
            showItemDetails: true,
        },

        labels: {
            singular: 'Trade Setting',
            plural: 'Trade Settings',
            key: 'trade-setting',
        },

        saveAlertInfo: {
            title: t('Trade Setting Configuration'),
            description: t('Configure duration, win percentages, amount limits, and preset buttons for this trade option.'),
        },
    };
}
